def parseInteger(s):
    n = len(s)
    i = 0
    neg = False
    if i < n and (s[i] == '+' or s[i] == '-'):
        neg = s[i] == '-'
        i += 1
    cap = 2 ** 31
    v = 0
    while i < n and '0' <= s[i] <= '9':
        v = v * 10 + ord(s[i]) - 48
        if v >= cap:
            v = cap
            break
        i += 1
    if neg:
        return -v
    return min(v, cap - 1)
